96:    // Implementation of the service binder interface.
97:    private class InitialLockSetupServiceImpl extends IInitialLockSetupService.Stub {
98:
99:        @Override
100:        public int getServiceVersion() {
101:            return InitialLockSetupConstants.LIBRARY_VERSION;
102:        }
103:
104:        @Override
105:        public LockConfig getLockConfig(@LockTypes int lockType) {
106:            // All lock types currently are configured the same.
107:            switch (lockType) {
108:                case LockTypes.PASSWORD:
109:                    // fall through
110:                case LockTypes.PIN:
111:                    // fall through
112:                case LockTypes.PATTERN:
113:                    return new LockConfig(/* enabled= */ true,
114:                            LockPatternUtils.MIN_LOCK_PATTERN_SIZE);
115:            }
116:            return null;
117:        }
118:
119:        @Override
120:        @ValidateLockFlags
121:        public int checkValidLock(@LockTypes int lockType, byte[] password) {
122:            PasswordHelper passwordHelper;
123:            switch (lockType) {
124:                case LockTypes.PASSWORD:
125:                    passwordHelper = new PasswordHelper(getApplicationContext(),
126:                            /* isPin= */ false, getUserId());
127:                    return passwordHelper.validateSetupWizard(password);
128:                case LockTypes.PIN:
129:                    passwordHelper = new PasswordHelper(getApplicationContext(),
130:                            /* isPin= */ true, getUserId());
131:                    return passwordHelper.validateSetupWizard(password);
132:                case LockTypes.PATTERN:
133:                    return password.length >= LockPatternUtils.MIN_LOCK_PATTERN_SIZE
134:                            ? 0 : ValidateLockFlags.INVALID_LENGTH;
135:                default:
136:                    LOG.e("other lock type, returning generic error");
137:                    return ValidateLockFlags.INVALID_GENERIC;
138:            }
139:        }
140:
141:        @Override
142:        @SetLockCodes
143:        public int setLock(@LockTypes int lockType, byte[] password) {
144:            int userId = UserHandle.myUserId();
145:            LockPatternUtils lockPatternUtils = new LockPatternUtils(
146:                    InitialLockSetupService.this.getApplicationContext());
147:            int currentPassword = lockPatternUtils.getKeyguardStoredPasswordQuality(userId);
148:            if (currentPassword != DevicePolicyManager.PASSWORD_QUALITY_UNSPECIFIED) {
149:                LOG.v("Password already set, rejecting call to setLock");
150:                return SetLockCodes.FAIL_LOCK_EXISTS;
151:            }
152:            if (!InitialLockSetupHelper.isValidLockResultCode(checkValidLock(lockType, password))) {
153:                LOG.v("Password is not valid, rejecting call to setLock");
154:                return SetLockCodes.FAIL_LOCK_INVALID;
155:            }
156:
157:            boolean success = false;
158:            try {
159:                switch (lockType) {
160:                    case LockTypes.PASSWORD:
161:                        // Need to remove setup wizard lib byte array encoding and use the
162:                        // LockPatternUtils encoding.
163:                        CharSequence passwordStr =
164:                                InitialLockSetupHelper.byteArrayToCharSequence(password);
165:                        lockPatternUtils.setLockCredential(
166:                                LockscreenCredential.createPassword(passwordStr),
167:                                /* savedPassword= */ LockscreenCredential.createNone(),
168:                                userId);
169:                        success = true;
170:                        break;
171:                    case LockTypes.PIN:
172:                        // Need to remove setup wizard lib byte array encoding and use the
173:                        // LockPatternUtils encoding.
174:                        CharSequence pinStr =
175:                                InitialLockSetupHelper.byteArrayToCharSequence(password);
176:                        lockPatternUtils.setLockCredential(
177:                                LockscreenCredential.createPin(pinStr),
178:                                /* savedPassword= */ LockscreenCredential.createNone(),
179:                                userId);
180:                        success = true;
181:                        break;
182:                    case LockTypes.PATTERN:
183:                        // Need to remove the setup wizard lib pattern encoding and use the
184:                        // LockPatternUtils pattern format.
185:                        List<LockPatternView.Cell> pattern = toSettingsPattern(password);
186:                        lockPatternUtils.setLockCredential(
187:                                LockscreenCredential.createPattern(pattern),
188:                                /* savedPassword= */ LockscreenCredential.createNone(),
189:                                userId);
190:                        pattern.clear();
191:                        success = true;
192:                        break;
193:                    default:
194:                        LOG.e("Unknown lock type, returning a failure");
195:                }
196:            } catch (Exception e) {
197:                LOG.e("Save lock exception", e);
198:                success = false;
199:            }
200:            Arrays.fill(password, (byte) 0);
201:            return success ? SetLockCodes.SUCCESS : SetLockCodes.FAIL_LOCK_GENERIC;
202:        }
203:    }
